// SCHRITT 1+2 - Authentifizierung und Eingabevalidierung.
// Dieser Node wirft nie eine Exception: jeder Abbruchgrund wird als
// fehler_code weitergereicht, damit Retell immer eine valide Antwort bekommt.
// Selbst ein unerwarteter Fehler endet in "unauthorized" - im Zweifel zu.
const notfall_id = String(Date.now()) + '-fehler';
try {
  const eingang = $input.first().json;
  const headers = eingang.headers || {};
  const body = eingang.body || {};
  const query = eingang.query || {};

  // Das Secret liegt serverseitig in der Umgebungsvariablen AK_WEBHOOK_SECRET
  // und steht bewusst nirgends im Workflow.
  const erwartet = String($env.AK_WEBHOOK_SECRET || '');
  // n8n liefert Header-Namen kleingeschrieben; die zweite Variante ist nur Absicherung.
  const gesendet = String(headers['x-ak-auth'] || headers['X-AK-Auth'] || '');

  // Vergleich in konstanter Zeit, damit die Antwortzeit nichts ueber das Secret verraet.
  function gleich(a, b) {
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
    return diff === 0;
  }

  // Zwei Aufrufformate werden unterstuetzt:
  //  a) direkt   { kunde_id, agent_typ, action, params }   - z.B. per curl
  //  b) Retell   { name, args, call }                      - Custom Function
  // kunde_id und agent_typ werden BEVORZUGT aus der Query der Tool-URL gelesen.
  // Grund: den Body fuellt bei Retell das Sprachmodell, die URL steht fest im
  // Agenten. So kann kein Anrufer im Gespraech den Mandanten umbiegen.
  function feld(name) {
    const ausQuery = query[name];
    if (ausQuery !== undefined && ausQuery !== null && String(ausQuery).trim() !== '') {
      return String(ausQuery).trim();
    }
    const ausBody = body[name];
    return String(ausBody == null ? '' : ausBody).trim();
  }

  function objekt(w) {
    if (w && typeof w === 'object' && !Array.isArray(w)) return w;
    // Manche Retell-Setups liefern die Argumente als JSON-Text.
    if (typeof w === 'string' && w.trim().startsWith('{')) {
      try {
        const p = JSON.parse(w);
        return (p && typeof p === 'object' && !Array.isArray(p)) ? p : null;
      } catch (e) { return null; }
    }
    return null;
  }

  const anruf = body.call || {};
  const basis = {
    request_id: String(Date.now()) + '-' + Math.random().toString(36).slice(2, 8),
    start_ms: Date.now(),
    kunde_id: feld('kunde_id'),
    agent_typ: feld('agent_typ'),
    // Bei Retell ist der Tool-Name die Action; er ist im Agenten fest hinterlegt.
    action: feld('action') || String(body.name == null ? '' : body.name).trim(),
    params: objekt(body.params) || objekt(body.args) || {},
    call_id: String(body.call_id || anruf.call_id || ''),
    // Die Rufnummer stammt aus der Telefonie, nicht aus dem Gespraech. Sie ist
    // damit das einzige Merkmal, das ein Anrufer nicht frei behaupten kann.
    from_number: String(anruf.from_number || body.from_number || query.from_number || '').trim(),
    fehler_code: '',
    http_code: 200,
    message: '',
  };

  // Flacher Payload ("args only" bei Retell): alles ausser den Steuerfeldern
  // als params behandeln. Steuerfelder aus dem Body werden dabei bewusst
  // verworfen - sie kommen aus der Query.
  if (Object.keys(basis.params).length === 0) {
    const flach = {};
    Object.keys(body).forEach(k => {
      if (['kunde_id', 'agent_typ', 'action', 'params', 'args', 'name', 'call',
           'call_id', 'from_number'].indexOf(k) === -1) {
        flach[k] = body[k];
      }
    });
    basis.params = flach;
  }

  if (!erwartet) {
    // Kein Secret gesetzt = Fehlkonfiguration. Dann wird grundsaetzlich nichts durchgelassen.
    return [{ json: Object.assign({}, basis, { fehler_code: 'unauthorized', http_code: 401, message: 'unauthorized' }) }];
  }
  if (!gesendet || !gleich(gesendet, erwartet)) {
    return [{ json: Object.assign({}, basis, { fehler_code: 'unauthorized', http_code: 401, message: 'unauthorized' }) }];
  }
  if (!basis.kunde_id || !basis.agent_typ || !basis.action) {
    return [{ json: Object.assign({}, basis, { fehler_code: 'invalid_request', message: 'invalid request' }) }];
  }
  return [{ json: basis }];
} catch (e) {
  // Haeufigster realer Fall: $env ist gesperrt (N8N_BLOCK_ENV_ACCESS_IN_NODE).
  // Dann darf auf keinen Fall durchgelassen werden.
  return [{ json: {
    request_id: notfall_id, start_ms: Date.now(), kunde_id: '', agent_typ: '',
    action: '', params: {}, call_id: '', from_number: '',
    fehler_code: 'unauthorized', http_code: 401, message: 'unauthorized',
  } }];
}

// SCHRITT 3 - Kunden-Config auswerten. Es gibt bewusst KEINEN Default-Kunden:
// ohne passende, aktive Zeile wird die Anfrage abgelehnt. Das ist der Kern
// der Mandantentrennung - ab hier traegt jeder Folgeschritt genau diese Config.
const anfrage = $('Auth und Validierung').first().json;

try {
  const roh = $input.all().map(i => i.json).filter(z => z && z.kunde_id);

  function jsonFeld(wert, standard) {
    if (wert === null || wert === undefined || wert === '') return standard;
    if (typeof wert === 'object') return wert;
    try { return JSON.parse(String(wert)); } catch (e) { return standard; }
  }

  if (roh.length === 0) {
    return [{ json: Object.assign({}, anfrage, { fehler_code: 'unknown_kunde', message: 'unknown kunde_id' }) }];
  }
  if (roh.length > 1) {
    // Zwei Zeilen mit derselben kunde_id: welche gilt, waere Zufall - und der
    // Zufall wuerde ueber Kalender und Absendernummer entscheiden.
    return [{ json: Object.assign({}, anfrage, { fehler_code: 'config_mehrdeutig', message: 'config mehrdeutig' }) }];
  }

  const z = roh[0];
  // aktiv kann als Boolean oder als Text aus der DataTable kommen.
  const aktiv = z.aktiv === true || String(z.aktiv).toLowerCase() === 'true';
  if (!aktiv) {
    return [{ json: Object.assign({}, anfrage, { fehler_code: 'kunde_inaktiv', message: 'kunde inaktiv' }) }];
  }

  const config = {
    kunde_id: String(z.kunde_id),
    kunde_name: String(z.kunde_name || z.kunde_id),
    zeitzone: String(z.zeitzone || 'Europe/Berlin'),
    // Kalender. Die API-Basis kommt bewusst NICHT aus der Kundenzeile: sonst
    // koennte eine Config-Zeile den gemeinsamen Cal.com-Key an einen fremden
    // Host schicken. Abweichungen nur serverseitig ueber AK_CAL_API_BASE.
    kalender_typ: String(z.kalender_typ || 'calcom'),
    cal_api_base: String($env.AK_CAL_API_BASE || 'https://api.cal.com/v2').replace(/\/+$/, ''),
    cal_event_type_id: String(z.cal_event_type_id || ''),
    cal_username: String(z.cal_username || ''),
    buchung_platzhalter_email: String(z.buchung_platzhalter_email || ''),
    // Telefonie
    sms_from: String(z.sms_from || ''),
    twilio_account_sid: String(z.twilio_account_sid || ''),
    // Nur diese Vorwahlen duerfen angeschrieben werden.
    sms_prefixe: jsonFeld(z.sms_prefixe, ['+49']),
    // CRM
    crm_typ: String(z.crm_typ || 'none'),
    crm_quelle: String(z.crm_quelle || ''),
    crm_blatt: String(z.crm_blatt || 'Tabelle1'),
    // Bereitschaft
    dispatch_kanal: String(z.dispatch_kanal || ''),
    dispatch_ziel: String(z.dispatch_ziel || ''),
    // Freiform
    system_endpoints: jsonFeld(z.system_endpoints, {}),
    sms_vorlagen: jsonFeld(z.sms_vorlagen, {}),
    // Name der Umgebungsvariablen mit dem Token fuer die Kundensysteme.
    system_token_env: String(z.system_token_env || ''),
  };

  // Sicherheitsnetz: die geladene Config muss zur angefragten kunde_id gehoeren.
  if (config.kunde_id !== anfrage.kunde_id) {
    return [{ json: Object.assign({}, anfrage, { fehler_code: 'config_mismatch', message: 'config mismatch' }) }];
  }

  // Optionale Einschraenkung: welcher Agent darf welche Action ausloesen.
  // Leere Liste = alles erlaubt.
  const erlaubt = jsonFeld(z.erlaubte_actions, []);
  if (Array.isArray(erlaubt) && erlaubt.length > 0 && erlaubt.indexOf(anfrage.action) === -1) {
    return [{ json: Object.assign({}, anfrage, { fehler_code: 'action_gesperrt', message: 'action nicht erlaubt' }) }];
  }

  return [{ json: Object.assign({}, anfrage, { config: config }) }];
} catch (e) {
  return [{ json: Object.assign({}, anfrage, { fehler_code: 'config_fehler', message: 'config fehler' }) }];
}

// Fallback des Routers: action existiert nicht. Bewusst keine Liste der
// gueltigen Actions in der Antwort - der Agent soll nicht raten koennen.
const e = $input.first().json;
return [{ json: Object.assign({}, e, { fehler_code: 'unknown_action', message: 'unknown action' }) }];

// SCHRITT 5 - Einheitliche Antwort. Alle Pfade (Auth-Fehler, unbekannter
// Kunde, unbekannte Action, Sub-Workflow-Ergebnis, Sub-Workflow-Absturz)
// muenden hier und ergeben immer { success, data, message }.
let anfrage = {};
try { anfrage = $('Auth und Validierung').first().json || {}; } catch (e) { anfrage = {}; }

let success = false;
let data = {};
let message = 'unerwartete antwort';
let http_code = 200;
let details = '';

try {
  const item = $input.first().json || {};

  if (item.fehler_code) {
    message = String(item.message || item.fehler_code);
    http_code = Number(item.http_code || 200);
    details = String(item.fehler_code);
  } else if (item.error) {
    // Sub-Workflow ist gelaufen, hat aber eine Exception geworfen
    // (onError = continueRegularOutput). Details bleiben im Log, nicht in der Antwort.
    message = 'interner fehler';
    details = String((item.error && (item.error.message || item.error.name)) || 'sub_fehler').slice(0, 200);
  } else if (typeof item.success === 'boolean') {
    success = item.success;
    data = (item.data && typeof item.data === 'object') ? item.data : {};
    message = String(item.message || '');
  }
} catch (e) {
  message = 'interner fehler';
  details = 'antwort_fehler';
}

return [{ json: {
  success: success,
  data: data,
  message: message,
  http_code: http_code,
  // Felder ab hier nur fuers Logging, sie sind nicht Teil der Antwort an Retell.
  request_id: String(anfrage.request_id || ''),
  kunde_id: String(anfrage.kunde_id || ''),
  agent_typ: String(anfrage.agent_typ || ''),
  action: String(anfrage.action || ''),
  call_id: String(anfrage.call_id || ''),
  details: details,
  dauer_ms: Date.now() - Number(anfrage.start_ms || Date.now()),
} }];
